css:
.succession-sim-container {
    padding: 28px 24px 36px;
    background: linear-gradient(180deg, #0f1d3a 0%, #0c1730 100%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #e8eaf0;
    letter-spacing: 0.005em;
}

.succession-sim-container * {
    box-sizing: border-box;
}

.succession-sim-container .succession-sim-header {
    border-bottom: 1px solid rgba(184,148,95,0.28);
    padding: 0 0 22px 0;
    margin-bottom: 28px;
}
.succession-sim-container .succession-sim-tag {
    color: #b8945f;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.18em;
    margin-bottom: 8px;
}
.succession-sim-container .succession-sim-header h1 {
    color: #f3e9d2;
    font-size: 1.65rem;
    font-weight: 600;
    margin: 0 0 6px 0;
    letter-spacing: 0.01em;
}
.succession-sim-container .succession-sim-subtitle {
    color: #9aa3b6;
    font-size: 0.95rem;
    font-style: italic;
}

.succession-sim-container .succession-sim-phase-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #16264a;
    border-left: 3px solid #b8945f;
    padding: 14px 20px;
    margin-bottom: 24px;
}
.succession-sim-container .succession-sim-phase-period {
    color: #9aa3b6;
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.14em;
}
.succession-sim-container .succession-sim-phase-period strong {
    color: #f3e9d2;
    margin-left: 8px;
    font-size: 1.05rem;
    font-weight: 600;
}
.succession-sim-container .succession-sim-phase-title {
    color: #f3e9d2;
    font-size: 1.05rem;
    font-weight: 500;
    letter-spacing: 0.02em;
}

.succession-sim-container .succession-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(190px, 1fr));
    gap: 14px;
    margin-bottom: 28px;
}
.succession-sim-container .succession-sim-kpi-card {
    background: #16264a;
    border: 1px solid rgba(255,255,255,0.05);
    border-top: 3px solid #4a5a7a;
    padding: 18px 18px 16px;
    position: relative;
}
.succession-sim-container .succession-sim-kpi-ego    { border-top-color: #b8945f; }
.succession-sim-container .succession-sim-kpi-slate  { border-top-color: #5cb3a3; }
.succession-sim-container .succession-sim-kpi-board  { border-top-color: #8aa3c7; }
.succession-sim-container .succession-sim-kpi-process { border-top-color: #cc7a6a; }
.succession-sim-container .succession-sim-kpi-label {
    color: #9aa3b6;
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.16em;
    margin-bottom: 10px;
}
.succession-sim-container .succession-sim-kpi-value {
    font-size: 2.1rem;
    font-weight: 600;
    color: #f3e9d2;
    line-height: 1;
    margin-bottom: 10px;
    transition: color 0.3s ease;
}
.succession-sim-container .succession-sim-kpi-note {
    color: #6c7790;
    font-size: 0.74rem;
    font-style: italic;
}

.succession-sim-container .succession-sim-briefing {
    background: #f6f1e3;
    color: #1a2237;
    padding: 22px 26px 24px;
    margin-bottom: 28px;
    border-left: 4px solid #b8945f;
    box-shadow: 0 4px 14px rgba(0,0,0,0.25);
}
.succession-sim-container .succession-sim-briefing-label {
    color: #b8945f;
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.18em;
    margin-bottom: 10px;
    font-weight: 600;
}
.succession-sim-container .succession-sim-briefing-text {
    color: #2a3553;
    font-size: 0.95rem;
    line-height: 1.65;
    font-family: Georgia, 'Times New Roman', serif;
}
.succession-sim-container .succession-sim-briefing-text em {
    color: #5c4422;
    font-style: italic;
}
.succession-sim-container .succession-sim-briefing-text strong {
    color: #1a2237;
    font-weight: 600;
}
.succession-sim-container .succession-sim-briefing-text blockquote {
    border-left: 2px solid #b8945f;
    padding: 6px 16px;
    margin: 10px 0;
    color: #4a3a20;
    font-style: italic;
}

.succession-sim-container .succession-sim-controls {
    background: #16264a;
    border: 1px solid rgba(255,255,255,0.06);
    padding: 24px 24px 20px;
    margin-bottom: 24px;
}
.succession-sim-container .succession-sim-controls h3 {
    color: #f3e9d2;
    font-size: 1.05rem;
    font-weight: 600;
    margin: 0 0 8px 0;
    letter-spacing: 0.02em;
}
.succession-sim-container .succession-sim-controls-help {
    color: #9aa3b6;
    font-size: 0.86rem;
    line-height: 1.55;
    margin: 0 0 18px 0;
    font-style: italic;
}

.succession-sim-container .succession-sim-candidate-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(310px, 1fr));
    gap: 12px;
    margin-bottom: 18px;
}
.succession-sim-container .succession-sim-candidate-card {
    display: flex;
    gap: 12px;
    background: #0f1d3a;
    border: 1px solid rgba(255,255,255,0.07);
    padding: 14px 16px;
    cursor: pointer;
    margin: 0;
    transition: border-color 0.2s ease, background 0.2s ease;
}
.succession-sim-container .succession-sim-candidate-card:hover {
    border-color: rgba(184,148,95,0.45);
    background: #11203f;
}
.succession-sim-container .succession-sim-candidate-card:has(input:checked) {
    border-color: #b8945f;
    background: rgba(184,148,95,0.08);
    box-shadow: inset 3px 0 0 #b8945f;
}
.succession-sim-container .succession-sim-candidate-checkbox {
    margin-top: 4px;
    accent-color: #b8945f;
    width: 16px;
    height: 16px;
    flex-shrink: 0;
}
.succession-sim-container .succession-sim-candidate-body {
    flex: 1;
    min-width: 0;
}
.succession-sim-container .succession-sim-candidate-head {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    gap: 10px;
    margin-bottom: 4px;
}
.succession-sim-container .succession-sim-candidate-name {
    color: #f3e9d2;
    font-size: 0.95rem;
    font-weight: 600;
    line-height: 1.3;
}
.succession-sim-container .succession-sim-candidate-tag {
    font-size: 0.66rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    padding: 2px 7px;
    border-radius: 2px;
    flex-shrink: 0;
    white-space: nowrap;
    font-weight: 600;
}
.succession-sim-container .succession-sim-candidate-card[data-tag="warning"] .succession-sim-candidate-tag {
    color: #cc7a6a;
    background: rgba(204,122,106,0.12);
}
.succession-sim-container .succession-sim-candidate-card[data-tag="neutral"] .succession-sim-candidate-tag {
    color: #8aa3c7;
    background: rgba(138,163,199,0.12);
}
.succession-sim-container .succession-sim-candidate-card[data-tag="variance"] .succession-sim-candidate-tag {
    color: #5cb3a3;
    background: rgba(92,179,163,0.14);
}
.succession-sim-container .succession-sim-candidate-role {
    color: #9aa3b6;
    font-size: 0.78rem;
    margin-bottom: 8px;
    letter-spacing: 0.02em;
}
.succession-sim-container .succession-sim-candidate-desc {
    color: #c2cad9;
    font-size: 0.83rem;
    line-height: 1.5;
}

.succession-sim-container .succession-sim-dev-grid {
    display: flex;
    flex-direction: column;
    gap: 10px;
    margin-bottom: 18px;
}
.succession-sim-container .succession-sim-dev-row {
    display: grid;
    grid-template-columns: 1fr 280px;
    gap: 14px;
    align-items: center;
    background: #0f1d3a;
    border: 1px solid rgba(255,255,255,0.06);
    padding: 12px 16px;
}
.succession-sim-container .succession-sim-dev-name {
    color: #f3e9d2;
    font-size: 0.95rem;
    font-weight: 500;
}
.succession-sim-container .succession-sim-dev-role {
    color: #9aa3b6;
    font-size: 0.78rem;
    font-weight: 400;
    margin-left: 6px;
}
.succession-sim-container .succession-sim-dev-select {
    width: 100%;
}

.succession-sim-container .succession-sim-radio-list {
    display: flex;
    flex-direction: column;
    gap: 10px;
}
.succession-sim-container .succession-sim-radio-card {
    display: flex;
    gap: 12px;
    align-items: flex-start;
    background: #0f1d3a;
    border: 1px solid rgba(255,255,255,0.07);
    padding: 14px 16px;
    cursor: pointer;
    margin: 0;
    transition: border-color 0.2s ease, background 0.2s ease;
}
.succession-sim-container .succession-sim-radio-card:hover {
    border-color: rgba(184,148,95,0.4);
    background: #11203f;
}
.succession-sim-container .succession-sim-radio-card:has(input:checked) {
    border-color: #b8945f;
    background: rgba(184,148,95,0.08);
    box-shadow: inset 3px 0 0 #b8945f;
}
.succession-sim-container .succession-sim-radio-card input[type="radio"] {
    accent-color: #b8945f;
    margin-top: 4px;
    width: 16px;
    height: 16px;
    flex-shrink: 0;
}
.succession-sim-container .succession-sim-radio-title {
    color: #f3e9d2;
    font-size: 0.95rem;
    font-weight: 600;
    margin-bottom: 4px;
}
.succession-sim-container .succession-sim-radio-desc {
    color: #c2cad9;
    font-size: 0.84rem;
    line-height: 1.5;
}

.succession-sim-container .succession-sim-aux {
    display: flex;
    flex-direction: column;
    gap: 14px;
    padding: 16px 0 4px;
    border-top: 1px solid rgba(255,255,255,0.06);
    margin-top: 14px;
}
.succession-sim-container .succession-sim-aux-row {
    display: flex;
    flex-direction: column;
    gap: 6px;
}
.succession-sim-container .succession-sim-aux-row label {
    color: #b8945f;
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    font-weight: 500;
}
.succession-sim-container .succession-sim-select,
.succession-sim-container .succession-sim-dev-select,
.succession-sim-container select {
    background: #0a1428;
    border: 1px solid #2a3a5a;
    color: #e8eaf0;
    padding: 8px 12px;
    font-size: 0.88rem;
    width: 100%;
    border-radius: 0;
    transition: border-color 0.2s ease;
}
.succession-sim-container select:focus {
    outline: none;
    border-color: #b8945f;
}
.succession-sim-container select option {
    background: #0a1428;
    color: #e8eaf0;
}

.succession-sim-container .succession-sim-action-row {
    display: flex;
    justify-content: flex-end;
    align-items: center;
    gap: 12px;
    margin-bottom: 28px;
}
.succession-sim-container .succession-sim-submit {
    background: #b8945f;
    border: 1px solid #b8945f;
    color: #1a2237;
    padding: 10px 26px;
    font-size: 0.86rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.14em;
    border-radius: 0;
    transition: background 0.2s ease;
}
.succession-sim-container .succession-sim-submit:hover {
    background: #c9a570;
    border-color: #c9a570;
    color: #0f1d3a;
}
.succession-sim-container .succession-sim-undo {
    background: transparent;
    border: 1px solid rgba(255,255,255,0.18);
    color: #9aa3b6;
    padding: 8px 16px;
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    border-radius: 0;
}
.succession-sim-container .succession-sim-undo:hover {
    border-color: #cc7a6a;
    color: #cc7a6a;
}

.succession-sim-container .succession-sim-section-title {
    color: #b8945f;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.16em;
    margin-bottom: 12px;
    font-weight: 600;
}
.succession-sim-container .succession-sim-history-wrap {
    background: #16264a;
    border: 1px solid rgba(255,255,255,0.05);
    padding: 18px 20px;
    margin-bottom: 24px;
}
.succession-sim-container #usfHistoryTable {
    color: #e8eaf0;
    width: 100%;
    margin: 0;
    background: transparent;
}
.succession-sim-container #usfHistoryTable thead th {
    color: #9aa3b6;
    border-bottom: 1px solid rgba(184,148,95,0.3);
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    font-weight: 600;
    padding: 8px 10px;
    background: transparent;
}
.succession-sim-container #usfHistoryTable tbody td {
    color: #c2cad9;
    border-top: 1px solid rgba(255,255,255,0.06);
    font-size: 0.86rem;
    padding: 10px 10px;
    background: transparent;
}
.succession-sim-container #usfHistoryTable tbody tr:hover td {
    background: rgba(184,148,95,0.05);
    color: #f3e9d2;
}

.succession-sim-container .succession-sim-chart-wrap {
    background: #16264a;
    border: 1px solid rgba(255,255,255,0.05);
    padding: 18px 20px 22px;
    height: 360px;
    margin-bottom: 16px;
}
.succession-sim-container #scoreChart {
    max-height: 290px !important;
}

@media (max-width: 768px) {
    .succession-sim-container { padding: 18px 14px 28px; }
    .succession-sim-container .succession-sim-header h1 { font-size: 1.3rem; }
    .succession-sim-container .succession-sim-phase-bar { flex-direction: column; align-items: flex-start; gap: 8px; }
    .succession-sim-container .succession-sim-kpi-grid { grid-template-columns: repeat(2, 1fr); }
    .succession-sim-container .succession-sim-candidate-grid { grid-template-columns: 1fr; }
    .succession-sim-container .succession-sim-dev-row { grid-template-columns: 1fr; gap: 8px; }
    .succession-sim-container .succession-sim-action-row { flex-direction: column-reverse; align-items: stretch; }
    .succession-sim-container .succession-sim-submit { width: 100%; }
}

.succession-sim-container :focus-visible,
.succession-sim-container button:focus-visible,
.succession-sim-container select:focus-visible,
.succession-sim-container input:focus-visible {
    outline: 3px solid #1a2744;
    outline-offset: 2px;
}
.succession-sim-completion { margin: 0 0 20px 0; }
.succession-sim-debrief {
    background: #ffffff; border: 1px solid #d6d9df; border-left: 5px solid #1a2744;
    border-radius: 4px; padding: 20px 24px; color: #1f2937;
}
.succession-sim-debrief h3 { margin: 0 0 12px 0; font-size: 1.15rem; }
.succession-sim-debrief h4 { margin: 18px 0 8px 0; font-size: 0.95rem; }
.succession-sim-debrief-table { width: 100%; border-collapse: collapse; }
.succession-sim-debrief-table th, .succession-sim-debrief-table td {
    text-align: left; padding: 6px 8px; border-bottom: 1px solid #e6e8ec; font-size: 0.9rem; color: #1f2937;
}
.succession-sim-debrief-table th { font-weight: 600; width: 55%; }
@media (prefers-reduced-motion: reduce) {
    .succession-sim-container *, .succession-sim-container *::before, .succession-sim-container *::after {
        animation-duration: 0.001ms !important; animation-iteration-count: 1 !important;
        transition-duration: 0.001ms !important; scroll-behavior: auto !important;
    }
}

js:
/* EQIL guard 1.3 (2026-10-08). Shared block, identical in every sim except SEED and MODE.
   1. Choice decisions start with no option selected and a seeded option order
      (MODE blank: empty selection, original order, for sims that address options by index).
   2. Render timers set while scoring a round wait until the period has advanced.
   3. getHint reads the round that was just scored.
   4. Where the runtime has no eventBus (Open player), a minimal one emits the platform events.
   5. Summary labels and insights returned as translation keys are translated for the platform default debrief.
   6. The framework t() is bound to its instance, so sims that copy it into a local variable keep working.
   7. (1.1) Checkboxes the view ticks by default start unticked until the player ticks them. A restored or
      resumed game keeps its ticks, disabled boxes are left alone, and a tick the player made is never cleared.
   8. (1.2) Text the sim wrote from its own translation table follows the language: after a switch, and whenever
      the sim writes text, a string from another language's table becomes the same key's string in the current one.
   9. (1.2) Randomness drawn while initialising or scoring comes from a generator kept in domainState, so undoing
      a round and submitting it again replays it exactly instead of re-rolling it.
  10. (1.2) Once the run is complete the submit button is disabled; an undo that reopens the run enables it again.
  11. (1.3) A choice keeps its order only when its texts read as a scale (a leading number, %, currency, or two level
      words). Numeric option values alone no longer count: many decisions with named options use 0, 1, 2 as values.
  12. (1.3) The seeded order also depends on the round, so options rebuilt each round are not in the same order
      every round. The same round (a redraw, a language switch, an undo, a resumed game) keeps its order.
   Reviews: Express/testing/eqil_reports/2026-09/EQIL_Portfolio_Finding_open-catalog-review_2026-09-28.md,
   2026-10/EQIL_Portfolio_Finding_model-sweep_2026-10-06.md (EQIL v1.2.0 §15, gates G-F and G-H) */
var __eqilGuard = (function () {
    var SEED = "1505";
    var MODE = "";   // blank: the sim addresses options by position, so no inserted placeholder and no shuffle; empty: placeholder and seeded shuffle
    var TXT = {
        en: ["Choose an option", "Choose an option in every decision before continuing."],
        es: ["Elige una opción", "Elige una opción en cada decisión antes de continuar."],
        ca: ["Tria una opció", "Tria una opció a cada decisió abans de continuar."],
        pt: ["Escolha uma opção", "Escolha uma opção em cada decisão antes de continuar."],
        fr: ["Choisissez une option", "Choisissez une option pour chaque décision avant de continuer."]
    };
    var LEVEL = ["none", "low", "medium", "moderate", "high", "very ", "minimal", "maximum", "conservative", "aggressive",
        "ningun", "bajo", "baja", "medio", "media", "moderad", "alto", "alta", "muy ", "mínim", "máxim", "conservador", "agresiv"];
    var later = window.setTimeout.bind(window);
    var submitted = null;
    var lastRound = null;
    var queued = false;
    var styled = false;
    var groups = {};
    var restoring = false;
    var resumed = false;

    var bus = null;
    function sim() { return window.mySimulation || null; }
    function miniBus() {
        var h = {};
        return {
            on: function (n, f) { (h[n] = h[n] || []).push(f); },
            off: function (n, f) { var a = h[n] || [], k = a.indexOf(f); if (k >= 0) { a.splice(k, 1); } },
            emit: function (n, d) { var a = (h[n] || []).slice(); for (var i = 0; i < a.length; i++) { try { a[i](d); } catch (e) {} } }
        };
    }
    function polyfill(f) {
        if (!f || f.eventBus) { return; }
        bus = miniBus();
        f.eventBus = bus;
        if (typeof f.undo === "function") {
            var u = f.undo;
            f.undo = function () { var r = u.apply(this, arguments); bus.emit("period:undone", this.state); return r; };
        }
        if (typeof f.setLang === "function") {
            var sl = f.setLang;
            f.setLang = function (l) {
                var r = sl.apply(this, arguments);
                bus.emit("language:changed", { lang: l });
                try { document.dispatchEvent(new CustomEvent("express:langchanged", { detail: { lang: l } })); } catch (e) {}
                return r;
            };
        }
    }
    function announce(state, res) {
        if (!bus || !state) { return; }
        var p0 = state.currentPeriod, t0 = Date.now();
        (function check() {
            if (String(state.currentPeriod) !== String(p0) || Date.now() - t0 > 4000) { bus.emit("period:submitted", { results: res, period: p0 }); }
            else { later(check, 40); }
        })();
    }
    function lang() {
        var l = "";
        try { if (window.vcI18n && window.vcI18n._lang) { l = window.vcI18n._lang; } } catch (e) {}
        try { if (!l && sim() && sim().lang) { l = sim().lang; } } catch (e) {}
        if (!l) { l = document.documentElement.lang || "en"; }
        l = String(l).toLowerCase().slice(0, 2);
        return TXT[l] ? l : "en";
    }
    function roundKey() { var f = sim(); return f && f.state ? String(f.state.currentPeriod) : ""; }
    function hash(s) {
        var h = 2166136261;
        for (var i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); }
        return h >>> 0;
    }
    function rand(seed) {
        var a = seed;
        return function () {
            a = (a + 0x6D2B79F5) | 0;
            var t = Math.imul(a ^ (a >>> 15), 1 | a);
            t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
            return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
        };
    }
    function permute(items, key) {
        var r = rand(hash(key)), a = items.slice();
        for (var i = a.length - 1; i > 0; i--) { var j = Math.floor(r() * (i + 1)); var t = a[i]; a[i] = a[j]; a[j] = t; }
        return a;
    }
    function gameKey(name, values) {
        // 1.3: the round is part of the key, so a select rebuilt every round with the same id and values gets a new
        // order each round (1422 kept one order for all 9 rounds, so always picking the second option scored 88)
        var f = sim(), g = f && f.state && f.state.gameId;
        return SEED + "|" + (g || "") + "|" + roundKey() + "|" + name + "|" + values.join(",");
    }
    function shown(el) {
        for (var n = el; n && n.nodeType === 1; n = n.parentElement) {
            if (n.hidden || n.id === "usfp-overlay") { return false; }
            var cs = window.getComputedStyle ? window.getComputedStyle(n) : null;
            if (cs && (cs.display === "none" || cs.visibility === "hidden")) { return false; }
        }
        return true;
    }
    function skipped(el) {
