        getChartData(state) {
            var milestones = ['Start', 'T-24', 'T-15', 'T-9', 'T-3'];
            var __d = (state && state.domainState) || {};
            var labels = (__d.egoHistory || []).map(function(_, i) {
                return milestones[i] || ('M' + i);
            });
            return {
                scoreChart: {
                    labels: labels,
                    datasets: [
                        { data: __d.egoHistory || [] },
                        { data: __d.slateHistory || [] },
                        { data: __d.boardHistory || [] },
                        { data: __d.processHistory || [] }
                    ]
                }
            };
        }

        getHint(state, results) {
            if (results && results.hint) return results.hint;
            if (results && results.summary) return results.summary;
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: 'results.phaseLabel',   label: 'Decision moment', i18nKey: 'col_phase' },
                { key: 'results.decisionLabel', label: 'Choice', i18nKey: 'col_choice' },
                { key: 'results.ego',     label: 'Ego', i18nKey: 'col_ego' },
                { key: 'results.slate',   label: 'Slate', i18nKey: 'col_slate' },
                { key: 'results.board',   label: 'Board', i18nKey: 'col_board' },
                { key: 'results.process', label: 'Process', i18nKey: 'col_process' }
            ];
        }

        _composite(ds, state) {
            var lastOf = function(arr, fb) {
                return (arr && arr.length) ? arr[arr.length - 1] : fb;
            };
            var ego = lastOf(ds.egoHistory, ds.ego !== undefined ? ds.ego : 0);
            var slate = lastOf(ds.slateHistory, ds.slate !== undefined ? ds.slate : 0);
            var board = lastOf(ds.boardHistory, ds.board !== undefined ? ds.board : 0);
            var process = lastOf(ds.processHistory, ds.process !== undefined ? ds.process : 0);
            var dims = [ego, slate, board, process];
            var sum = 0, n = 0;
            for (var i = 0; i < dims.length; i++) {
                if (typeof dims[i] === 'number' && !isNaN(dims[i])) { sum += dims[i]; n++; }
            }
            var score = n ? (sum / n) : 0;
            score = Math.max(0, Math.min(100, score));
            var caps = [];
            if (process < 35) caps.push('processFailed');
            if (board < 35) caps.push('boardLost');
            if (caps.length) score = Math.min(score, 60);
            /* v1.2.0: one set of lines for grade and verdict; the top line moves from 85 to 90 so that a
               run carrying one of the teaching-note failure modes no longer reads as exemplary */
            var key = 'developing';
            if (score >= 55) key = 'serviceable';
            if (score >= 70) key = 'sound';
            if (score >= 90) key = 'exemplary';
            var grade = 'F';
            if (score >= 90) grade = 'A';
            else if (score >= 70) grade = 'B';
            else if (score >= 55) grade = 'C';
            else if (score >= 40) grade = 'D';
            return {
                /* platform score: the running composite of the four readings (the score the debrief grades),
                   already 0 to 100, rounded to a whole number; the debrief keeps its one decimal from score */
                overallScore: Math.max(0, Math.min(100, Math.round(score))),
                totalScore: parseFloat(score.toFixed(1)),
                composite: parseFloat(score.toFixed(1)),
                score: parseFloat(score.toFixed(1)),
                grade: grade,
                performanceKey: key,
                dims: { ego: ego, slate: slate, board: board, process: process },
                failureStates: caps
            };
        }

        formatCompletionMessage(summary) {
            var tt = function(k) { return window.mySimulation.t(k); };
            var s = summary || {};
            var rows = [
                [tt('sum_score'), (s.overallScore !== undefined ? s.overallScore : 0) + ' / 100 (' + (s.grade || '-') + ')'],
                [tt('sum_band'), s.performanceLabel || '']
            ];
            var html = '<div class="succession-sim-debrief" role="status" aria-live="polite">';
            html += '<h3>' + tt('debrief_title') + '</h3><table class="succession-sim-debrief-table"><tbody>';
            rows.forEach(function(r) { html += '<tr><th scope="row">' + r[0] + '</th><td>' + r[1] + '</td></tr>'; });
            html += '</tbody></table>';
            var tps = s.turningPoints || [];
            if (tps.length) {
                html += '<h4>' + tt('debrief_turning') + '</h4><ul>';
                tps.forEach(function(i) { html += '<li>' + i + '</li>'; });
                html += '</ul>';
            }
            var ins = s.insights || [];
            if (ins.length) {
                html += '<h4>' + tt('debrief_insights') + '</h4><ul>';
                ins.forEach(function(i) { html += '<li>' + i + '</li>'; });
                html += '</ul>';
            }
            html += '</div>';
            return html;
        }

        _turningPoints(d) {
            /* v1.2.0: name the teaching-note failure modes this run actually made, from its own record */
            var out = [];
            var slate = d.selectedSlate || [];
            if (slate.length) {
                var low = slate.filter(function(k) { return CANDIDATES[k] && CANDIDATES[k].similarity <= 4; }).length;
                if (low === 0) out.push(t('tp_mirror_slate'));
            }
            if (d.scanChoice === 'A') out.push(t('tp_scan_declined'));
            if (d.memoFormat === 'deck') out.push(t('tp_deck'));
            if (d.patriciaApproach === 'diminish') out.push(t('tp_diminish'));
            if (d.patriciaApproach === 'ignore') out.push(t('tp_omit'));
            return out;
        }

        getPerformanceSummary(history) {
            if (!history || !history.length) return {};
            var d = window.mySimulation.state.domainState;
            var insights = [];
            insights.push(t(d.ego >= 70 ? 'ins_ego_hi' : 'ins_ego_lo'));
            insights.push(t(d.slate >= 70 ? 'ins_slate_hi' : 'ins_slate_lo'));
            insights.push(t(d.board >= 70 ? 'ins_board_hi' : 'ins_board_lo'));
            insights.push(t(d.process >= 70 ? 'ins_process_hi' : 'ins_process_lo'));
            var __perf = (d.performance && d.performance.overallScore !== undefined)
                ? d.performance
                : this._composite(d, window.mySimulation.state);
            var __shown = (typeof __perf.score === 'number') ? __perf.score : __perf.overallScore;

            return {
                overallScore: __shown,
                totalScore: __shown,
                composite: __shown,
                score: __shown,
                grade: __perf.grade,
                performance: __perf.performanceKey,
                performanceKey: __perf.performanceKey,
                performanceLabel: t('band_' + __perf.performanceKey),
                failureStates: __perf.failureStates || [],
                turningPoints: this._turningPoints(d),
                insights: insights,
                ego: d.ego, slate: d.slate, board: d.board, process: d.process
            };
        }

